// Writes packages/sdk/src/core/version.ts from packages/sdk/package.json, so the user agent can never drift from the
// published version. Run by the sdk's build and lint scripts; the generated file is committed and a test checks it.
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");

export function versionSource(version) {
  return `// Generated by scripts/write-sdk-version.mjs from package.json. Do not edit.\nexport const SDK_VERSION = ${JSON.stringify(version)};\n`;
}

export const target = path.join(root, "packages", "sdk", "src", "core", "version.ts");
export const manifest = path.join(root, "packages", "sdk", "package.json");

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const { version } = JSON.parse(readFileSync(manifest, "utf8"));
  writeFileSync(target, versionSource(version));
}
